import {workflowSnapshot,refreshWorkflow} from './workflow.js';
import {agentState,publicationApproved,PARAGRAPH_AGENT} from './agents.js';
import {saveArtifactEdit} from './artifact-edits.js';
import {callAgent,aiConfigured,aiSettings} from './provider.js';
import {canEdit,workspaceState} from './workspace-client.js';
import {projectDetails,setProjectDetails} from './project-workspace.js';
import {paragraphEdit} from './project-snapshots.js';
import {readDocx} from './docx.js';
import {segments} from './engine.js';
import {digest,containsSecret,audit} from './security.js';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const articleState=run=>agentState(run,'rewrite').output?agentState(run,'rewrite'):agentState(run,'writing');
function selected(){const title=$('artifact-title').textContent;return title.includes('初稿')?'writing':'rewrite';}
function safeURL(value){if(!value)return '';try{const u=new URL(value);if(u.protocol==='https:'&&!u.username&&!u.password)return u.href;}catch{}throw Error('公開URLはhttpsから始まるURLを入力してください。');}
export async function evidenceRecords(run){const output=articleState(run)?.output,parts=output?.article?.split(/\n\s*\n/).filter(Boolean)||[];const records=projectDetails().evidence||[];return Promise.all(parts.map(async(text,i)=>({text,index:i,hash:await digest(text),record:null}))).then(items=>items.map(p=>({...p,record:records.find(r=>r.hash===p.hash)})));}
async function showEvidence(){const {run}=workflowSnapshot();$('evidence-dialog').showModal();if(!run){$('evidence-content').textContent='原稿を作成すると取材資料と見比べられます。';return;}const parts=await evidenceRecords(run),sources=[...segments(run.input.transcript).map(s=>({...s,type:'取材'})),...segments(run.input.sources,'S').map(s=>({...s,type:'調査資料'})),...segments(run.input.rules,'R').map(s=>({...s,type:'編集ルール'}))];$('evidence-content').innerHTML=parts.map(p=>`<section class="evidence-pair"><div><h3>段落 ${p.index+1}</h3><p class="document-text">${esc(p.text)}</p><span class="pill ${p.record?.status==='checked'?'mint':'pink'}">${p.record?.status==='checked'?'確認済み':'未確認'}</span></div><div><label for="evidence-source-${p.index}">確認する根拠</label><select id="evidence-source-${p.index}" data-evidence-source="${p.index}"><option value="">資料を選んでください</option>${sources.map(s=>`<option value="${s.id}" ${p.record?.sourceId===s.id?'selected':''}>${esc(s.type)} ${esc(s.id)} · ${esc(s.text.slice(0,70))}</option>`).join('')}</select><blockquote id="evidence-quote-${p.index}">${esc(sources.find(s=>s.id===p.record?.sourceId)?.text||'')}</blockquote><label for="evidence-note-${p.index}">確認メモ</label><textarea id="evidence-note-${p.index}" maxlength="500" placeholder="数値の対象・期間、引用の意図など">${esc(p.record?.note||'')}</textarea><button class="button secondary" data-evidence-confirm="${p.index}" ${!canEdit()?'disabled':''}>根拠を確認した</button></div></section>`).join('');for(const s of $('evidence-content').querySelectorAll('[data-evidence-source]'))s.onchange=()=>{$('evidence-quote-'+s.dataset.evidenceSource).textContent=sources.find(src=>src.id===s.value)?.text||'';};for(const b of $('evidence-content').querySelectorAll('[data-evidence-confirm]'))b.onclick=async()=>{if(!canEdit()||workflowSnapshot().busy)return;const p=parts[Number(b.dataset.evidenceConfirm)],sourceId=$('evidence-source-'+p.index).value;if(!sourceId){$('evidence-quote-'+p.index).textContent='先に根拠の資料を選んでください。';return;}const list=(projectDetails().evidence||[]).filter(r=>r.hash!==p.hash);list.push({hash:p.hash,sourceId,note:$('evidence-note-'+p.index).value.slice(0,500),status:'checked',time:new Date().toISOString()});setProjectDetails({evidence:list.slice(-100)});await showEvidence();};}
function showParagraph(){const {run,busy}=workflowSnapshot(),id=selected(),output=run&&agentState(run,id).output;if(busy||!canEdit()||!output?.article)return;const parts=output.article.split(/\n\s*\n/);$('paragraph-select').innerHTML=parts.map((text,i)=>`<option value="${i}">${i+1} · ${esc(text.slice(0,70))}</option>`).join('');$('paragraph-select').onchange=()=>{$('paragraph-original').value=parts[Number($('paragraph-select').value)];$('paragraph-result').hidden=true;};$('paragraph-select').onchange();$('paragraph-request').value='';$('paragraph-message').textContent='';$('paragraph-generate').disabled=false;$('paragraph-dialog').showModal();let controller;const original=JSON.stringify(output);$('paragraph-generate').onclick=async()=>{if(!aiConfigured()||!aiSettings().consent){$('paragraph-message').textContent='先に資料の取り扱いを確認してください。';return;}if(run.demo){$('paragraph-message').textContent='固定の操作サンプルでは作り直せません。通常の記事でお試しください。';return;}if(run.attempts>=48){$('paragraph-message').textContent='この制作ではこれ以上作り直せません。';return;}if(!canEdit()||workflowSnapshot().busy)return;const index=Number($('paragraph-select').value),request=$('paragraph-request').value.trim();if(!request){$('paragraph-message').textContent='直したいことを入力してください。';return;}$('paragraph-generate').disabled=true;$('paragraph-message').textContent='選んだ段落を作り直しています。';controller=new AbortController();try{run.attempts++;const result=await callAgent({id:'paragraph',role:'generation',schema:PARAGRAPH_AGENT.schema,instruction:PARAGRAPH_AGENT.instruction,input:{paragraph:parts[index],request,article:output.article,transcript:run.input.transcript,sources:run.input.sources,rules:run.input.rules},signal:controller.signal,web:false,maxTokens:3000});run.usageRecords.push({agent:'paragraph',time:new Date().toISOString(),...result.usage});if(!result.output.paragraph.trim()||result.output.paragraph.length>15000)throw Error('文章を作成できませんでした。');$('paragraph-new').value=result.output.paragraph;$('paragraph-result').hidden=false;$('paragraph-message').textContent='現在の文章と見比べて、採用するか確認してください。';await audit(run,'paragraph_generated',{index,outputHash:await digest(result.output)});$('paragraph-apply').onclick=async()=>{try{if(JSON.stringify(agentState(run,id).output)!==original)throw Error('原稿が変わりました。開き直してください。');const next={...output,article:paragraphEdit(output.article,index,$('paragraph-new').value)};await saveArtifactEdit(run,id,next);$('paragraph-dialog').close();refreshWorkflow();}catch(e){$('paragraph-message').textContent=e.message;}};}catch(e){$('paragraph-message').textContent=e.message||'作り直せませんでした。元の文章は変更していません。';}finally{$('paragraph-generate').disabled=false;refreshWorkflow();}};$('paragraph-dialog').onclose=()=>controller?.abort();}
async function importWord(file){const {run,busy}=workflowSnapshot(),id=selected(),output=run&&agentState(run,id).output;if(busy||!canEdit()||!output?.article)return;try{let text=await readDocx(file);if(containsSecret(text)||text.length>60000)throw Error('パスワードなどの秘密の情報を含まない、60,000文字以内の原稿をご利用ください。');const lines=text.split('\n');if(lines[0].trim()===output.title.trim())text=lines.slice(1).join('\n').trim();$('word-before').textContent=output.article;$('word-after').value=text;$('word-message').textContent='';$('word-import-dialog').showModal();const original=JSON.stringify(output);$('word-apply').onclick=async()=>{try{if(workflowSnapshot().busy||!canEdit())return;if(JSON.stringify(agentState(run,id).output)!==original)throw Error('原稿が変わりました。開き直してください。');await saveArtifactEdit(run,id,{...output,article:$('word-after').value});$('word-import-dialog').close();refreshWorkflow();}catch(e){$('word-message').textContent=e.message;}};}catch(e){$('workflow-status').hidden=false;$('workflow-status').textContent=e.message;}}
async function showPublications(){const {run}=workflowSnapshot(),list=projectDetails().publications||[];const platforms=['Instagram','YouTube','Webサイト'];$('publications-content').innerHTML=platforms.map((platform,i)=>{const p=list.find(r=>r.platform===platform)||{};return `<section class="publication-card"><h3>${platform}</h3><label for="post-assignee-${i}">担当者</label><input id="post-assignee-${i}" maxlength="253" value="${esc(p.assignee||'')}"><label for="post-date-${i}">投稿予定日</label><input id="post-date-${i}" type="date" value="${esc(p.date||'')}"><label for="post-state-${i}">状態</label><select id="post-state-${i}">${['下書き','確認中','投稿予定','公開済み'].map(s=>`<option ${p.status===s?'selected':''}>${s}</option>`).join('')}</select><label for="post-url-${i}">公開URL</label><input id="post-url-${i}" type="url" maxlength="1000" value="${esc(p.url||'')}">${p.approvalHash&&p.approvalHash!==run?.approvals?.publication?.hash?'<p class="notice">原稿が変わったため、投稿内容を再確認してください。</p>':''}</section>`;}).join('')+`<button id="publications-save" class="button primary" ${!canEdit()?'disabled':''}>投稿の予定・実績を保存</button>`;$('publications-message').textContent='';$('publications-dialog').showModal();$('publications-save').onclick=async()=>{try{if(!canEdit())return;const rows=platforms.map((platform,i)=>({platform,assignee:$('post-assignee-'+i).value.slice(0,253),date:$('post-date-'+i).value,status:$('post-state-'+i).value,url:safeURL($('post-url-'+i).value.trim())}));if(rows.some(p=>p.status==='公開済み')){if(!run||!await publicationApproved(run))throw Error('公開用データを確認してから、公開済みにしてください。');if(rows.some(p=>p.status==='公開済み'&&!p.url))throw Error('公開済みの投稿にはURLを記録してください。');}setProjectDetails({publications:rows.map(p=>({...p,approvalHash:p.status==='公開済み'?run.approvals.publication.hash:null}))});$('publications-message').textContent='投稿の予定・実績を保存しました。';}catch(e){$('publications-message').textContent=e.message;}};}
export function initPracticalEditing(){$('evidence-open').onclick=()=>void showEvidence();$('publications-open').onclick=()=>void showPublications();$('artifact-paragraph').onclick=showParagraph;$('artifact-import-word').onclick=()=>{$('artifact-word-file').value='';$('artifact-word-file').click();};$('artifact-word-file').onchange=e=>{const file=e.target.files?.[0];if(file)void importWord(file);};}
